import{z as B,x as i,o as e,c as d,q as l,j as o,D as E,d as t,s as n,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"模型提取攻击","description":"","frontmatter":{"title":"模型提取攻击","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-extraction-attack.md","filePath":"llm/model-extraction-attack.md","lastUpdated":1791063341000}'),p={name:"llm/model-extraction-attack.md"};function m(c,a,h,D,C,f){const r=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="模型提取攻击" tabindex="-1">模型提取攻击 <a class="header-anchor" href="#模型提取攻击" aria-label="Permalink to &quot;模型提取攻击&quot;">​</a></h1><div class="epigraph"><p>接口若稳定地回答查询，对手就可以拟合一个替代模型。保护的是行为与成本，不是把权重藏在机房里就结束。</p><footer>—— Tramèr 等对模型提取的早期工作；对照 API 蒸馏与水印讨论</footer></div><p><a href="/llm/dp-sgd">上一课</a>保护训练样本。本课转向部署：模型提取——用查询–响应拟合替代模型，逼近教师的决策边界或生成分布。缺口不是 <a href="/llm/sequence-distill">序列蒸馏</a> 作为训练技术，而是<strong>未经授权、以 API 为教师</strong>的行为盗窃。后课指纹用来检测「像不像被偷的那份行为」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>蒸馏课假定你拥有教师。提取假定对手只有黑盒或灰盒接口。语言模型上，提取表现为：大规模采样补全、用补全当 SFT 数据、得到能力接近的学生。缺口是把「开源复现」与「打 API 搬家」分开：前者用公开权重，后者消耗你的计量与可能的专有行为。</p><p>本课讲机制与监测，不提供高效提取的查询策略或绕过条款的办法。</p><p><span class="marginnote">提取的目标可以是任务准确率，不必是逐权重复现。对分类器，少量查询就能逼近边界；对 LLM，成本主要在 token 与多样性覆盖。</span></p><p><span class="marginnote">术语翻译：黑盒指对手只能看到「输入—输出」，拿不到权重、梯度或内部状态；灰盒指还能看到部分内部信息，比如每个 token 的对数概率。接口暴露的概率信息越多，对手拟合学生越省事，这是 API 文档要不要返回 logprobs 时的安全考量之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御侧公开讨论过的层：查询速率与账户风控、输出水印（<a href="/llm/kirchenbauer-watermark">Kirchenbauer</a> / <a href="/llm/synthid-watermark">SynthID</a>）便于事后举证、条款与审计、对异常长会话的抽样。监测：同一前缀的查询密度、学生模型在你特有错误模式上的吻合（后课指纹）。技术上无法让黑盒 API 在任意查询下既有用又不可学——只能提高成本与举证。</p>',10)),(e(),o(s,null,{default:E(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20API%5B%22%E6%95%99%E5%B8%88%20API%22%5D%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E5%AD%A6%E7%94%9F%E6%95%B0%E6%8D%AE%22%5D%0A%20%20D%20--%3E%20S%5B%22%E6%9B%BF%E4%BB%A3%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20S%20--%3E%20DET%5B%22%E6%8C%87%E7%BA%B9%20%2F%20%E6%B0%B4%E5%8D%B0%E6%A3%80%E6%B5%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"若教师是确定性函数，查询就是标签。语言模型带随机采样，对手可以用低温度或多次采样降噪。学生容量足够时，行为在训练支持上可逼近；支持外仍可能分叉。这与 DP 正交：DP 不阻止学公共行为。",-1)),(e(),o(s,null,{default:E(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AF%B9%E6%89%8B%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20T%7B%22%E6%95%99%E5%B8%88%E8%BE%93%E5%87%BA%E6%80%A7%E8%B4%A8%22%7D%0A%20%20T%20--%3E%7C%22%E7%A1%AE%E5%AE%9A%E6%80%A7%EF%BC%9A%E5%90%8C%E8%BE%93%E5%85%A5%E5%90%8C%E8%BE%93%E5%87%BA%22%7C%20L1%5B%22%E6%9F%A5%E8%AF%A2%E5%8D%B3%E5%B8%A6%E6%A0%87%E7%AD%BE%E6%A0%B7%E6%9C%AC%EF%BC%8C%E7%9B%B4%E6%8E%A5%E6%8B%9F%E5%90%88%22%5D%0A%20%20T%20--%3E%7C%22%E9%9A%8F%E6%9C%BA%E9%87%87%E6%A0%B7%EF%BC%9A%E5%90%8C%E8%BE%93%E5%85%A5%E5%A4%9A%E8%BE%93%E5%87%BA%22%7C%20L2%5B%22%E9%9C%80%E4%BD%8E%E6%B8%A9%E6%88%96%E5%A4%9A%E6%AC%A1%E9%87%87%E6%A0%B7%E6%8A%95%E7%A5%A8%E9%99%8D%E5%99%AA%22%5D%0A%20%20L1%20--%3E%20S%5B%22%E5%AD%A6%E7%94%9F%E9%80%BC%E8%BF%91%E6%95%99%E5%B8%88%E8%A1%8C%E4%B8%BA%22%5D%0A%20%20L2%20--%3E%20S%0A%20%20S%20--%3E%7C%22%E8%AE%AD%E7%BB%83%E6%94%AF%E6%8C%81%E4%B9%8B%E5%A4%96%22%7C%20D%5B%22%E8%A1%8C%E4%B8%BA%E5%8F%AF%E8%83%BD%E5%88%86%E5%8F%89%EF%BC%8C%E6%8C%87%E7%BA%B9%E5%8F%AF%E4%B8%BE%E8%AF%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">数字实例：假设复现一个可用学生需要 10 亿次查询、平均每次 1 千 token，就是约 1 万亿 token 的搬运量。防御的目标不是让提取「不可能」，而是把这条账单、账户数量与审计痕迹抬到对对手不划算——这正是速率限制与风控的定价逻辑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写攻击脚本。合法知识蒸馏、公开技术报告复现，不是本课对象。下一课指纹是检测工具，不是阻止查询的防火墙。<span class="marginnote">常见误区：初学者容易以为「权重加密保存、机房门禁严格」就等于模型安全。提取偷的是接口行为，不是文件——只要 API 还在对公众回答，行为就在持续外泄，防线必须建在查询侧。</span>安全等级与 RSP 会把「可提取的危险能力」当成部署门槛的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>提取：用接口行为拟合替代模型。</li><li>目标常是行为而非权重；成本在查询。</li><li>防御是成本、水印与审计，不是密码学保密。</li><li>出处：Tramèr 等；蒸馏与水印课。</li></ul>',5))])}const _=B(p,[["render",m]]);export{F as __pageData,_ as default};
